"""Pure, deterministic CSV and aligned-table output."""

from __future__ import annotations

from .model import Result


def _value_text(value: int | float | str) -> str:
    return repr(value) if isinstance(value, float) else str(value)


def _csv_field(value: int | float | str | None) -> str:
    if value is None:
        return ""
    text = _value_text(value)
    if (
        not text
        or any(char in text for char in ',"\r\n')
        or text.startswith(" ")
        or text.endswith(" ")
    ):
        return '"' + text.replace('"', '""') + '"'
    return text


def format_csv(result: Result) -> str:
    """Return LF-terminated CSV, distinguishing NULL from empty TEXT."""
    lines = [",".join(_csv_field(name) for name in result.columns)]
    lines.extend(
        ",".join(_csv_field(value) for value in row) for row in result.rows
    )
    return "\n".join(lines) + "\n"


def _table_cell(value: int | float | str | None) -> str:
    text = "NULL" if value is None else _value_text(value)
    return text.replace("\r", "\\r").replace("\n", "\\n")


def format_table(result: Result) -> str:
    """Return an escaped, code-point-aligned table with a row-count footer."""
    headers = [_table_cell(name) for name in result.columns]
    rows = [[_table_cell(value) for value in row] for row in result.rows]
    widths = [len(header) for header in headers]
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))

    lines = [" | ".join(cell.ljust(width) for cell, width in zip(headers, widths))]
    lines.append("-+-".join("-" * width for width in widths))
    for values, cells in zip(result.rows, rows):
        lines.append(" | ".join(
            cell.rjust(width) if isinstance(value, (int, float)) else cell.ljust(width)
            for value, cell, width in zip(values, cells, widths)
        ))
    count = len(result.rows)
    lines.append(f"({count} {'row' if count == 1 else 'rows'})")
    return "\n".join(line.rstrip(" ") for line in lines) + "\n"

